<?php require dirname(__DIR__).'/inc/page_helpers.php';admin_required();if(page_post()){check_csrf();$action=(string)($_POST['action']??'');if($action==='create'){$name=trim((string)($_POST['name']??''));$type=(string)($_POST['type']??'other');$price=max(0,(int)($_POST['price']??0));$stock=($_POST['stock']??'')===''?null:max(0,(int)$_POST['stock']);$desc=trim((string)($_POST['description']??''));if($name!==''&&in_array($type,['hat','shirt','pants','tshirt','face','head','other'],true)){$q=$db->prepare('INSERT INTO catalog_items(name,type,description,price,stock) VALUES(?,?,?,?,?)');$q->execute([$name,$type,$desc,$price,$stock]);notice('Catalog item created.');}}elseif($action==='delete'){$db->prepare('DELETE FROM catalog_items WHERE id=?')->execute([(int)$_POST['id']]);notice('Catalog item deleted.');}go('/Admin/Catalog.php');}$items=$db->query('SELECT id,name,type,price,stock,sold_count FROM catalog_items ORDER BY id DESC LIMIT 200')->fetchAll();page_start('Catalog Administration');?><section class="Panel"><h1>Catalog Administration</h1><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="create"><label>Name<input name="name" maxlength="120" required></label><label>Type<select name="type"><?php foreach(['hat','shirt','pants','tshirt','face','head','other'] as $t):?><option><?=e($t)?></option><?php endforeach;?></select></label><label>Description<textarea name="description"></textarea></label><label>Price in Tickets<input type="number" min="0" name="price" value="0"></label><label>Stock (blank = unlimited)<input type="number" min="0" name="stock"></label><button class="Button">Create item</button></form><h2>Existing items</h2><table class="Grid"><tr><th>Item</th><th>Price</th><th>Stock</th><th>Sold</th><th></th></tr><?php foreach($items as $i):?><tr><td><?=e($i['name'])?></td><td><?=(int)$i['price']?></td><td><?=($i['stock']===null?'Unlimited':(int)$i['stock'])?></td><td><?=(int)$i['sold_count']?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$i['id']?>"><button>Delete</button></form></td></tr><?php endforeach;?></table></section><?php page_end();?>